import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {resolve} from 'node:path';
import {ConnectionManager} from '../../packages/core/src/connections.js';
import {Comparisons} from '../../packages/core/src/comparisons.js';
import {Combinations} from '../../packages/core/src/combinations.js';
import {ProfileSchema,type ConnectionProfile,type CompareInput} from '../../packages/protocol/src/index.js';
import {ddlQuote} from '../../packages/core/src/ddl-syntax.js';
export async function comparisonContract(profile:ConnectionProfile,password:string){
  let profiles:ConnectionProfile[]=[];const manager=new ConnectionManager({list:()=>profiles,save:async p=>{profiles=[...profiles.filter(v=>v.id!==p.id),p];},remove:async id=>{profiles=profiles.filter(v=>v.id!==id);}},{runnerPath:resolve('dist/sqlite-runner.cjs')});
  const service=new Comparisons(manager),combinations=new Combinations(service),server={...profile,id:'compare-server-'+randomUUID()},local=ProfileSchema.parse({id:'compare-local-'+randomUUID(),name:'SQLite comparison source',driver:'sqlite',storage:'memory'}),name='cmp_'+randomUUID().replaceAll('-','').slice(0,12),q=(s:string)=>ddlQuote(s,profile.driver),target=q(profile.driver==='postgresql'?'public':profile.database!)+'.'+q(name);
  try{
    await manager.save(server);await manager.setPassword(server.id,password,'session');await manager.save(local);const left=await manager.connect(local.id),right=await manager.connect(server.id);
    await left.query('CREATE TABLE t(id INTEGER PRIMARY KEY,v TEXT,n INTEGER,b BLOB)');await left.query("INSERT INTO t VALUES(1,'中文 source',9223372036854775807,x'0001ff'),(2,'insert',2,NULL)");
    await right.query(`CREATE TABLE ${target}(id BIGINT PRIMARY KEY,v TEXT,n BIGINT,b ${profile.driver==='postgresql'?'BYTEA':'BLOB'})`);await right.query(`INSERT INTO ${target} VALUES(1,'old',1,NULL),(3,'delete',3,NULL)`);
    const input:CompareInput={source:{kind:'table',profileId:local.id,table:'t'},target:{kind:'table',profileId:server.id,table:target},pairs:['id','v','n','b'].map(c=>({source:c,target:c,key:c==='id',mode:c==='id'||c==='n'?'numeric':'strict'})),limit:100};
    const c=await service.compare(input);assert.deepEqual(c.counts,{'source-only':1,'target-only':1,changed:1,equal:0});const preview=service.previewSync(c.token,service.differenceIds(c.token));assert.match(preview.sql,/INSERT/);const result=await service.apply(preview.token);assert.equal(result.status,'succeeded',result.error);const equal=await service.compare(input);assert.equal(equal.counts.equal,2);assert.equal(service.page(equal.token).total,0);
    const joined=await combinations.run({operation:'join',sources:[input.source,input.target],type:'full',pairs:[{left:'id',right:'id',mode:'numeric'}],keepRightKeys:false,limit:100});assert.equal(joined.rows,2);const joinedRows=JSON.parse(combinations.export(joined.id,'json'));assert.deepEqual(joinedRows.rows[0][2],{type:'integer',value:'9223372036854775807'});assert.deepEqual(joinedRows.rows[0][3],{type:'binary',base64:'AAH/'});
    const union=await combinations.run({operation:'union',sources:[input.source,input.target],limit:100});assert.equal(union.rows,4);const stacked=await combinations.run({operation:'join',sources:[{kind:'derived',id:union.id},input.target],type:'inner',pairs:[{left:union.columns.find(c=>c.name==='id')!.key,right:'id',mode:'numeric'}],keepRightKeys:false,limit:100});assert.equal(stacked.rows,4);assert(combinations.lineage(stacked.id).some(n=>n.kind==='union'));assert.equal(stacked.truncated,false);
    // Every mutation is made after capture, including insertion outside the changed keys.
    for(const change of [`INSERT INTO ${target} VALUES(8,'external',8,NULL)`,`DELETE FROM ${target} WHERE id=2`,`UPDATE ${target} SET v='external' WHERE id=2`,`ALTER TABLE ${target} ADD COLUMN extra TEXT`]){
      await left.query("UPDATE t SET v='next source' WHERE id=1");const compared=await service.compare(input),plan=service.previewSync(compared.token,service.differenceIds(compared.token));await right.query(change);const before=await right.query(`SELECT * FROM ${target} ORDER BY id`),failed=await service.apply(plan.token);assert.equal(failed.status,'failed');assert.match(failed.error!,/changed after comparison/);assert.deepEqual((await right.query(`SELECT * FROM ${target} ORDER BY id`)).rows,before.rows);service.forget(compared.token);
      if(change.includes('ADD COLUMN'))await right.query(`ALTER TABLE ${target} DROP COLUMN extra`);await right.query(`DELETE FROM ${target}`);await right.query(`INSERT INTO ${target} VALUES(1,'old',1,NULL),(2,'insert',2,NULL)`);
    }
    const sample=await service.compare({...input,limit:1});assert(sample.source.truncated&&sample.target.truncated);assert.equal(sample.canSync,false);service.forget(sample.token);
    // Reverse direction is a real server -> SQLite write, not only a swapped label.
    await right.query(`UPDATE ${target} SET v='server wins' WHERE id=1`);const reverse=await service.compare({...input,source:input.target,target:input.source}),plan=service.previewSync(reverse.token,service.differenceIds(reverse.token));assert.equal((await service.apply(plan.token)).status,'succeeded');assert.equal((await left.query('SELECT v FROM t WHERE id=1')).rows[0]?.c0,'server wins');
    const owner='compare-open-transaction';await (await manager.lease(server.id,owner)).query('BEGIN');const txCompare=await service.compare(input);await left.query("UPDATE t SET v='transaction guard' WHERE id=1");service.forget(txCompare.token);const tx=await service.compare(input),txPlan=service.previewSync(tx.token,service.differenceIds(tx.token));const blocked=await service.apply(txPlan.token);assert.equal(blocked.status,'failed');assert.match(blocked.error!,/transactions/);assert.equal(manager.documentSession(owner)?.transactionState,'active');await manager.releaseLease(owner);
    // The server can accept a write yet transform it without an error/warning.
    // Verify the actual persisted values inside the same transaction and rollback.
    if(profile.driver==='postgresql'){await right.query(`CREATE FUNCTION ${q('public')}.${q(name+'_transform')}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.v := upper(NEW.v); RETURN NEW; END $$`);await right.query(`CREATE TRIGGER ${q(name+'_transform')} BEFORE UPDATE ON ${target} FOR EACH ROW EXECUTE FUNCTION ${q('public')}.${q(name+'_transform')}()`);}else await right.query(`CREATE TRIGGER ${q(name+'_transform')} BEFORE UPDATE ON ${target} FOR EACH ROW SET NEW.v=UPPER(NEW.v)`);
    const transformed=await service.compare(input),transformPlan=service.previewSync(transformed.token,service.differenceIds(transformed.token)),unchanged=await right.query(`SELECT * FROM ${target} ORDER BY id`),rejected=await service.apply(transformPlan.token);assert.equal(rejected.status,'failed');assert.equal(rejected.committed,false);assert.match(rejected.error!,/converted or changed.*before commit/);assert.deepEqual((await right.query(`SELECT * FROM ${target} ORDER BY id`)).rows,unchanged.rows);service.forget(transformed.token);
    await right.query(`DROP TRIGGER ${q(name+'_transform')}${profile.driver==='postgresql'?' ON '+target:''}`);if(profile.driver==='postgresql')await right.query(`DROP FUNCTION ${q('public')}.${q(name+'_transform')}()`);
    // Verify an actual competing insertion is blocked while a slowed-down write
    // holds the snapshot lock, rather than merely racing two preflight reads.
    if(profile.driver==='postgresql'){await right.query(`CREATE FUNCTION ${q('public')}.${q(name+'_pause')}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_sleep(3); RETURN NEW; END $$`);await right.query(`CREATE TRIGGER ${q(name+'_pause')} BEFORE UPDATE ON ${target} FOR EACH ROW EXECUTE FUNCTION ${q('public')}.${q(name+'_pause')}()`);}else await right.query(`CREATE TRIGGER ${q(name+'_pause')} BEFORE UPDATE ON ${target} FOR EACH ROW DO SLEEP(3)`);
    await left.query("UPDATE t SET v='locked sync' WHERE id=1");const concurrency=await service.compare(input),writePlan=service.previewSync(concurrency.token,service.differenceIds(concurrency.token)),external=await manager.lease(server.id,'competing-insert');await external.query(profile.driver==='postgresql'?"SET lock_timeout='500ms'":'SET innodb_lock_wait_timeout=1');
    const applying=service.apply(writePlan.token);let sleeping=false;
    for(let attempt=0;attempt<40;attempt++){const count=await right.query(profile.driver==='postgresql'?`SELECT count(*) FROM pg_stat_activity WHERE wait_event='PgSleep' AND query LIKE '%${name}%'`:`SELECT count(*) FROM information_schema.PROCESSLIST WHERE STATE LIKE '%sleep%'`);if(Number(count.rows[0]?.c0)>0){sleeping=true;break;}await new Promise(r=>setTimeout(r,50));}
    if(!sleeping){const outcome=await applying;throw new Error('Did not observe the database trigger holding the synchronization write lock. Outcome: '+JSON.stringify(outcome));}
    await assert.rejects(external.query(`INSERT INTO ${target} VALUES(9,'competing insert',9,NULL)`),/lock.*timeout|timeout.*lock/i);const lockedResult=await applying;assert.equal(lockedResult.status,'succeeded',lockedResult.error);assert.equal((await right.query(`SELECT count(*) FROM ${target} WHERE id=9`)).rows[0]?.c0,0);await manager.releaseLease('competing-insert');
  }finally{await combinations.dispose();await service.dispose();await manager.close();}
}
